{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "physical activity may include walking, jumping rope, volleyball or other activity promoting fitness and well-being",
      "rationale": "Conveys the permitted activities and the fitness and well-being qualifier."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "physical activity may include walking, jumping rope, volleyball or other activity promoting fitness and well-being, structured movement breaks",
      "rationale": "Includes structured movement breaks among permitted forms of physical activity."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "time in physical education when students are physically active",
      "rationale": "Conveys that physical education time counts only when students are physically active."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Walking to and from class would not count as physical activity for this section.",
      "rationale": "States the exclusion and its section-specific scope."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "The bill would also exclude time when a student is permitted to use an electronic device from a provision concerning physical activity",
      "rationale": "Conveys the electronic-device exclusion but does not identify subsection (b)(2)(A)(ii) as its target. The supplied bill provides no substantive description of that provision that would otherwise identify it."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "allow a teacher to prevent a student from participating in physical activity to improve the student’s behavior",
      "rationale": "Conveys the teacher's authority, the participation restriction, and its behavioral purpose."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Beginning July 1, 2026, and applying to the 2026–2027 school year and each school year after that",
      "rationale": "Includes both the effective date and application to the specified school year and all subsequent school years."
    }
  ]
}
